{
  "id": "gold-si-8709ea8e-001",
  "doc_id": "8709ea8e088c85468be4e1ecbf4ea8cb41899d09a777f7e61986b798cb620a35",
  "lang": "si",
  "task": "short_answer_qa",
  "style": "concise",
  "split": "gold_eval",
  "messages": [
    {
      "role": "system",
      "content": "ඔබ ලබාදෙන පිළිතුරු සඳහා පහත ලබාදුන් සාදන දත්තම පමණක් භාවිතා කරන්න."
    },
    {
      "role": "user",
      "content": "HPB (Health Promotion Bureau) ශ්‍රී ලංකාවේ කුමන කටයුතු සඳහා විශිෂ්ටත්ව මධ්‍යස්ථානයක් ලෙස සඳහන් වී තිබේද?"
    },
    {
      "role": "assistant",
      "content": "health education, health promotion and publicity of health information."
    },
    {
      "role": "user",
      "content": "ඉහත පිළිතුර සඳහා සාධකය උපුටා දක්වන්න."
    },
    {
      "role": "assistant",
      "content": "The Health Promotion Bureau (HPB) is the centre of excellence in Sri Lanka for health education, health promotion and publicity of health information."
    }
  ]
}

{
  "id": "gold_si_hpb_org_001",
  "doc_id": "e0a9f022bb40a8afa6935d9cb336a0f486c6b6e8ea77a031a1fc823cabfa13b2",
  "lang": "si",
  "task": "short_answer_qa",
  "style": "concise",
  "split": "gold_eval",
  "messages": [
    {
      "role": "system",
      "content": "ඔබේ පිළිතුරු ලබා දෙනුයේ සපයන ලද පාඨයේ අන්තර්ගතය පමණක් පදනම් කරගෙනය. නව තොරතුරු නිර්මාණය නොකරන්න."
    },
